// TestPairVerbs is the device-facing pairing surface (device-pairing D1):
// POST /pair and GET /pair/{id}/wait answer with NO Authorization header (the
// only unauthenticated API surface), the create shape is {pairing_id, code},
// the per-IP burst is 429 rate_limited, and the token pickup is exactly-once
// (pending → approved-with-token → consumed, no token).
func TestPairVerbs(t *testing.T) {
	st := openAPIStore(t)
	devices := pairing.NewService(st, nil)
	h := New(Deps{AdminToken: adminToken, Store: st, Pairing: devices})
	ctx := context.Background()

	var firstID string
	t.Run("create_200_shape", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodPost, "/api/v1/pair", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var pr pairCreateResponse
		if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
			t.Fatalf("decode pairCreateResponse: %v", err)
		}
		if pr.PairingID == "" || pr.Code == "" {
			t.Fatalf("pairCreateResponse = %+v (want non-empty pairing_id + code)", pr)
		}
		firstID = pr.PairingID
	})

	t.Run("wait_pending_no_token", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/pair/"+firstID+"/wait", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var wr pairWaitResponse
		if err := json.NewDecoder(resp.Body).Decode(&wr); err != nil {
			t.Fatalf("decode pairWaitResponse: %v", err)
		}
		if wr.Status != "pending" || wr.DeviceToken != "" {
			t.Fatalf("pairWaitResponse = %+v (want pending, no device_token)", wr)
		}
	})

	t.Run("create_429_after_burst", func(t *testing.T) {
		// firstID already spent one of the 5/window slots: four more pass,
		// the sixth is 429 rate_limited.
		for i := 0; i < 4; i++ {
			resp := doRequest(t, h, http.MethodPost, "/api/v1/pair", "", "")
			resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("create %d/5: status = %d, want %d", i+2, resp.StatusCode, http.StatusOK)
			}
		}
		resp := doRequest(t, h, http.MethodPost, "/api/v1/pair", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusTooManyRequests {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusTooManyRequests)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "rate_limited" {
			t.Fatalf("error code = %q, want rate_limited", eb.Error.Code)
		}
	})

	t.Run("wait_unknown_id_404", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/pair/pair_nope/wait", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("wait_approved_token_once_then_consumed", func(t *testing.T) {
		// The admin verdict arrives through the service (the admin-verb wire
		// is TestPairingAdminVerbs's job); this test owns the device side.
		if _, err := devices.Approve(ctx, firstID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		pickup := doRequest(t, h, http.MethodGet, "/api/v1/pair/"+firstID+"/wait", "", "")
		defer pickup.Body.Close()
		if pickup.StatusCode != http.StatusOK {
			t.Fatalf("pickup status = %d, want %d", pickup.StatusCode, http.StatusOK)
		}
		var wr pairWaitResponse
		if err := json.NewDecoder(pickup.Body).Decode(&wr); err != nil {
			t.Fatalf("decode pickup: %v", err)
		}
		if wr.Status != "approved" || wr.DeviceToken == "" {
			t.Fatalf("pickup = %+v (want approved with the raw token, exactly once)", wr)
		}
		again := doRequest(t, h, http.MethodGet, "/api/v1/pair/"+firstID+"/wait", "", "")
		defer again.Body.Close()
		if again.StatusCode != http.StatusOK {
			t.Fatalf("post-pickup status = %d, want %d", again.StatusCode, http.StatusOK)
		}
		var wr2 pairWaitResponse
		if err := json.NewDecoder(again.Body).Decode(&wr2); err != nil {
			t.Fatalf("decode post-pickup: %v", err)
		}
		if wr2.Status != "consumed" || wr2.DeviceToken != "" {
			t.Fatalf("post-pickup = %+v (want consumed, token never re-issued)", wr2)
		}
	})
}

// TestPairingAdminVerbs is the admin pairing surface (device-pairing D2):
// the five admin-group verbs behind the admin token — pending-only list,
// approve/deny with 409 on dead requests, the device registry, revoke — and
// a minted device-token principal is 403-forbidden on all five.
func TestPairingAdminVerbs(t *testing.T) {
	st := openAPIStore(t)
	devices := pairing.NewService(st, nil)
	h := New(Deps{AdminToken: adminToken, Store: st, Pairing: devices})
	ctx := context.Background()

	// pairingRow mints one pending request straight through the service (the
	// device-facing wire is TestPairVerbs's job); distinct IPs keep the
	// per-IP windows independent.
	pairingRow := func(t *testing.T, ip string) pairing.Pairing {
		t.Helper()
		reqRow, err := devices.CreateRequest(ctx, ip)
		if err != nil {
			t.Fatalf("CreateRequest: %v", err)
		}
		return reqRow
	}

	t.Run("list_pending_and_approve", func(t *testing.T) {
		reqRow := pairingRow(t, "10.1.0.1")
		list := doRequest(t, h, http.MethodGet, "/api/v1/admin/pairings", "", adminToken)
		var lr pairingsResponse
		if err := json.NewDecoder(list.Body).Decode(&lr); err != nil {
			t.Fatalf("decode pairingsResponse: %v", err)
		}
		list.Body.Close()
		if list.StatusCode != http.StatusOK {
			t.Fatalf("list status = %d, want %d", list.StatusCode, http.StatusOK)
		}
		found := false
		for _, p := range lr.Pairings {
			if p.PairingID == reqRow.ID {
				found = true
				if p.Code != reqRow.Code || p.CreatedAt.IsZero() || p.ExpiresAt.IsZero() {
					t.Fatalf("pending row = %+v (want code + stamps round-tripped)", p)
				}
			}
		}
		if !found {
			t.Fatalf("pending pairing %s missing from list (%+v)", reqRow.ID, lr.Pairings)
		}

		approve := doRequest(t, h, http.MethodPost, "/api/v1/admin/pairings/"+reqRow.ID+"/approve", "", adminToken)
		defer approve.Body.Close()
		if approve.StatusCode != http.StatusOK {
			t.Fatalf("approve status = %d, want %d", approve.StatusCode, http.StatusOK)
		}
		var ar pairingActionResponse
		if err := json.NewDecoder(approve.Body).Decode(&ar); err != nil {
			t.Fatalf("decode pairingActionResponse: %v", err)
		}
		if ar.PairingID != reqRow.ID || ar.Status != "approved" {
			t.Fatalf("pairingActionResponse = %+v", ar)
		}

		// Pending-only list: the approved request has left the review queue.
		list2 := doRequest(t, h, http.MethodGet, "/api/v1/admin/pairings", "", adminToken)
		var lr2 pairingsResponse
		if err := json.NewDecoder(list2.Body).Decode(&lr2); err != nil {
			t.Fatalf("decode pairingsResponse: %v", err)
		}
		list2.Body.Close()
		for _, p := range lr2.Pairings {
			if p.PairingID == reqRow.ID {
				t.Fatalf("approved pairing %s still listed as pending", reqRow.ID)
			}
		}

		// Dead request: approving again is 409 conflict.
		reapprove := doRequest(t, h, http.MethodPost, "/api/v1/admin/pairings/"+reqRow.ID+"/approve", "", adminToken)
		defer reapprove.Body.Close()
		if reapprove.StatusCode != http.StatusConflict {
			t.Fatalf("re-approve status = %d, want %d", reapprove.StatusCode, http.StatusConflict)
		}
		if eb := decodeError(t, reapprove); eb.Error.Code != "conflict" {
			t.Fatalf("error code = %q, want conflict", eb.Error.Code)
		}
	})

	t.Run("deny_then_approve_409", func(t *testing.T) {
		reqRow := pairingRow(t, "10.1.0.2")
		deny := doRequest(t, h, http.MethodPost, "/api/v1/admin/pairings/"+reqRow.ID+"/deny", "", adminToken)
		deny.Body.Close()
		if deny.StatusCode != http.StatusOK {
			t.Fatalf("deny status = %d, want %d", deny.StatusCode, http.StatusOK)
		}
		approve := doRequest(t, h, http.MethodPost, "/api/v1/admin/pairings/"+reqRow.ID+"/approve", "", adminToken)
		defer approve.Body.Close()
		if approve.StatusCode != http.StatusConflict {
			t.Fatalf("approve-after-deny status = %d, want %d", approve.StatusCode, http.StatusConflict)
		}
	})

	t.Run("unknown_ids_404", func(t *testing.T) {
		for _, rr := range []struct{ method, path string }{
			{http.MethodPost, "/api/v1/admin/pairings/pair_nope/approve"},
			{http.MethodPost, "/api/v1/admin/pairings/pair_nope/deny"},
			{http.MethodDelete, "/api/v1/admin/devices/dev_nope"},
		} {
			resp := doRequest(t, h, rr.method, rr.path, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusNotFound {
				t.Fatalf("%s %s: status = %d, want %d", rr.method, rr.path, resp.StatusCode, http.StatusNotFound)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
				t.Fatalf("%s %s: error code = %q, want not_found", rr.method, rr.path, eb.Error.Code)
			}
		}
	})

	t.Run("devices_list_and_revoke", func(t *testing.T) {
		reqRow := pairingRow(t, "10.1.0.3")
		if _, err := devices.Approve(ctx, reqRow.ID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		out, err := devices.Wait(ctx, reqRow.ID)
		if err != nil || out.Token == "" {
			t.Fatalf("Wait: outcome=%+v err=%v", out, err)
		}

		// Earlier subtests approved pairings too, so the registry holds one
		// row per approve: this subtest's row is the one carrying its code.
		list := doRequest(t, h, http.MethodGet, "/api/v1/admin/devices", "", adminToken)
		var dr devicesResponse
		if err := json.NewDecoder(list.Body).Decode(&dr); err != nil {
			t.Fatalf("decode devicesResponse: %v", err)
		}
		list.Body.Close()
		if list.StatusCode != http.StatusOK {
			t.Fatalf("list status = %d, want %d", list.StatusCode, http.StatusOK)
		}
		var dev deviceDTO
		found := false
		for _, d := range dr.Devices {
			if d.Code == reqRow.Code {
				dev, found = d, true
				break
			}
		}
		if !found {
			t.Fatalf("device with code %s missing from %+v", reqRow.Code, dr.Devices)
		}
		if dev.DeviceID == "" || dev.CreatedAt.IsZero() {
			t.Fatalf("device row = %+v (want device_id + stamp)", dev)
		}

		revoke := doRequest(t, h, http.MethodDelete, "/api/v1/admin/devices/"+dev.DeviceID, "", adminToken)
		revoke.Body.Close()
		if revoke.StatusCode != http.StatusNoContent {
			t.Fatalf("revoke status = %d, want %d", revoke.StatusCode, http.StatusNoContent)
		}
		// Revoked token no longer authenticates: the next poll 401s.
		denied := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", out.Token)
		denied.Body.Close()
		if denied.StatusCode != http.StatusUnauthorized {
			t.Fatalf("revoked-token request status = %d, want %d", denied.StatusCode, http.StatusUnauthorized)
		}
	})

	t.Run("device_token_403_on_all_five", func(t *testing.T) {
		// Mint one real device credential (its own pairing, its own IP).
		reqRow := pairingRow(t, "10.1.0.4")
		if _, err := devices.Approve(ctx, reqRow.ID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		out, err := devices.Wait(ctx, reqRow.ID)
		if err != nil || out.Token == "" {
			t.Fatalf("Wait: outcome=%+v err=%v", out, err)
		}
		// A paired device reaches browse routes but is denied every admin
		// pairing verb (authZ: the admin group admits RoleAdmin only).
		for _, rr := range []struct{ method, path string }{
			{http.MethodGet, "/api/v1/admin/pairings"},
			{http.MethodPost, "/api/v1/admin/pairings/pair_x/approve"},
			{http.MethodPost, "/api/v1/admin/pairings/pair_x/deny"},
			{http.MethodGet, "/api/v1/admin/devices"},
			{http.MethodDelete, "/api/v1/admin/devices/dev_x"},
		} {
			resp := doRequest(t, h, rr.method, rr.path, "", out.Token)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusForbidden {
				t.Fatalf("%s %s with device token: status = %d, want %d", rr.method, rr.path, resp.StatusCode, http.StatusForbidden)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
				t.Fatalf("%s %s: error code = %q, want forbidden", rr.method, rr.path, eb.Error.Code)
			}
		}
	})
}
